arguments.command:
# Find code symbols near the SGen worker addresses (0x2f4b20, 0x2f4c84) and finalizer (0x2c1a40)
DBG=/tmp/sv-5442fb0ff60d4c0a9be312e9c0daed62/mono.debug
# Only look at text (code) symbols
aarch64-linux-gnu-nm --defined-only "$DBG" 2>/dev/null | grep -E '^ *[0-9a-f]+ [tTwW] ' | sort | awk -v pc1="0x2f4b20" -v pc2="0x2f4c84" '
BEGIN {
  t1=strtonum(pc1); t2=strtonum(pc2)
}
{
  addr=strtonum("0x"$1)
  if(addr<=t1){n1=$3; a1=addr}
  if(addr<=t2){n2=$3; a2=addr}
}
END {
  printf "0x2f4b20 -> %s+0x%x\n", n1, t1-a1
  printf "0x2f4c84 -> %s+0x%x\n", n2, t2-a2
}'

